import datetime as dt

def next_run(cron_expr: str) -> dt.datetime:
    parts = cron_expr.split()
    minute, hour, day, month = (int(p) if p != '*' else None for p in parts[:4])

    now = dt.datetime.now().replace(second=0, microsecond=0)
    y = now.year

    while True:
        try:
            cand = dt.datetime(y, month or now.month, day or now.day, hour or 0, minute or 0)
            if cand > now:
                if minute is None or cand.minute == minute:
                    if hour is None or cand.hour == hour:
                        if day is None or cand.day == day:
                            if month is None or cand.month == month:
                                return cand
        except ValueError:
            pass
        y += 1

# Test
