import psutil
import time
from datetime import datetime

def monitor_connections(host: str, interval_s: int) -> list[dict]:
    results = []
    end_time = time.time() + interval_s

    while time.time() < end_time:
        for conn in psutil.net_connections(kind='inet'):
            if conn.status == psutil.CONN_ESTABLISHED and conn.laddr and conn.laddr.ip == host:
                if conn.raddr:
                    results.append({
                        'timestamp': datetime.now().isoformat(),
                        'source_ip': conn.raddr.ip,
                        'source_port': conn.raddr.port
                    })
        time.sleep(1)

    return results
