import yaml

def generate_compose_file():
    compose_config = {
        "services": {
            "secure-comms": {
                "image": "sapo/internal-comms:e2ee-latest",
                "container_name": "sapo_secure_comms",
                "restart": "unless-stopped",
                "networks": ["sapo_internal_net"],
                "volumes": [
                    "e2ee_keys:/etc/comms/keys:ro",  # Read-only för nycklar
                    "comms_data:/var/lib/comms"
                ],
                "environment": {
                    "E2EE_ENABLED": "true",
                    "TLS_VERSION": "1.3"
                }
            }
        },
        "networks": {
            "sapo_internal_net": {
                "driver": "bridge",
                "internal": True  # Isolerar nätverket från extern åtkomst
            }
        },
        "volumes": {
            "e2ee_keys": {},
            "comms_data": {}
        }
    }

    with open("docker-compose.yml", "w") as f:
        yaml.dump(compose_config, f, sort_keys=False)

if __name__ == "__main__":
    generate_compose_file()
```

