def classify_document(text: str, categories: list[str]) -> str:
    """
    Klassificerar en text baserat på förekomsten av nyckelord för MSB.
    Returnerar den kategori som har flest träffar, eller 'Okänd' vid oavgjort.
    """
    text_lower = text.lower()
    scores = {category: 0 for category in categories}

    # Enkel nyckelordsbaserad matchning för samhällsstörningar
    keywords = {
        "driftstörning": ["strömavbrott", "avbrott", "driftstörning", "tele", "bredband"],
        "väder": ["storm", "översvämning", "regn", "snö", "blåst", "väder"],
        "it-incident": ["cyberattack", "phishing", "malware", "it-attack", "ransomware"],
        "olycka": ["brand", "kollision", "olycka", "räddning", "utryckning"]
    }

    for category in categories:
        for word in keywords.get(category, []):
            if word in text_lower:
                scores[category] += 1

    best_category = max(scores, key=scores.get)

    return best_category if scores[best_category] > 0 else "Okänd"
