import os
import stat

def audit_file_permissions(directory: str) -> list[dict]:
    """Granskar filrättigheter och identifierar world-writable filer."""
    insecure_files = []

    for root, _, files in os.walk(directory):
        for name in files:
            filepath = os.path.join(root, name)
            try:
                file_stat = os.stat(filepath)
                # Kontrollera om filen är skrivbar för "others" (world-writable)
                if file_stat.st_mode & stat.S_IWOTH:
                    insecure_files.append({
                        "file": filepath,
                        "permissions": oct(file_stat.st_mode & 0o777),
                        "issue": "World-writable"
                    })
            except OSError:
                continue

    return insecure_files
