import os

def find_writable_files(directory: str) -> list[str]:
    writable_files = []
    for root, _, files in os.walk(directory):
        for file in files:
            file_path = os.path.join(root, file)
            try:
                if os.access(file_path, os.W_OK):
                    writable_files.append(file_path)
            except OSError:
                continue
    return writable_files
