import re
from collections import Counter
from scapy.all import rdpcap, DNS, DNSQR

def analyze_dns_traffic(pcap_file: str) -> dict:
    results = {"dga": [], "tunneling": [], "exfiltration": []}
    queries = []

    try:
        packets = rdpcap(pcap_file)
    except Exception:
        return results

    for pkt in packets:
        if pkt.haslayer(DNS) and pkt.haslayer(DNSQR):
            qname = pkt[DNSQR].qname.decode('utf-8', errors='ignore').rstrip('.')
            if qname:
                queries.append(qname)

    for domain in queries:
        # DGA: Hög entropi och långt namn utan vokaler
        if len(domain.split('.')[0]) > 15 and not re.search(r'[aeiou]', domain, re.I):
            results["dga"].append(domain)

        # Tunneling: TXT-records eller extremt många subdomäner
        if domain.count('.') > 5:
            results["tunneling"].append(domain)

        # Exfiltration: Mycket lång subdomän (t.ex. Base64-kodad data)
        if len(domain.split('.')[0]) > 30:
            results["exfiltration"].append(domain)

    # Aggregera och returnera unika domäner med antal förekomster
    for key in results:
        results[key] = dict(Counter(results[key]))

    return results
```

