import re

def check_xss_vulnerability(html_input: str) -> list[str]:
    recommendations = []

    # Kontrollera efter vanliga XSS-mönster
    patterns = {
        r'<script.*?>': "Ta bort eller koda <script>-taggar.",
        r'javascript:': "Undvik 'javascript:'-URI:er i attribut.",
        r'on\w+\s*=': "Ta bort eller sanera event-hanterare (t.ex. onclick, onerror).",
        r'<iframe.*?>': "Undvik <iframe>-taggar om de inte är strikt nödvändiga.",
        r'<img[^>]+src\s*=\s*["\']?javascript:': "Sanera <img>-src-attribut för att förhindra javascript-körning."
    }

    for pattern, advice in patterns.items():
        if re.search(pattern, html_input, re.IGNORECASE):
            recommendations.append(advice)

    if not recommendations:
        recommendations.append("Inga uppenbara XSS-sårbarheter upptäckta. Använd alltid en etablerad HTML-sanerare för säkerhet.")

    return recommendations
