import re

def harden_ssh_config(config_path: str) -> dict:
    recommendations = {}
    insecure_settings = {
        'PermitRootLogin': 'no',
        'PasswordAuthentication': 'no',
        'PermitEmptyPasswords': 'no',
        'X11Forwarding': 'no',
        'Protocol': '2'
    }

    try:
        with open(config_path, 'r', encoding='utf-8') as f:
            content = f.read()
    except FileNotFoundError:
        return {"error": "Konfigurationsfilen hittades inte."}

    current_settings = {}
    for line in content.splitlines():
        line = line.strip()
        if not line or line.startswith('#'):
            continue
        parts = re.split(r'\s+', line, maxsplit=1)
        if len(parts) == 2:
            current_settings[parts[0]] = parts[1].strip()

    for setting, secure_value in insecure_settings.items():
        current_value = current_settings.get(setting)
        if current_value is None:
            recommendations[setting] = f"Saknas. Rekommenderat värde: '{secure_value}'"
        elif current_value.lower() != secure_value.lower():
            recommendations[setting] = f"Är '{current_value}'. Rekommenderat värde: '{secure_value}'"

    return recommendations
